-- Habbo's furniture this hotel does not have yet (123 classnames: Christmas 2026, NFT 2026 and others). Furnidata as on
-- habbo.com (sprite id, names, size, flags, line, revision, custom params); interaction and state count follow the rules of
-- scripts/import-habbo-catalog.py, with the states its furni asset animates. Habbo sells none of them yet (offer id -1), so
-- no catalog offers are added.
-- A hotel that already has the classname, or a furnidata row on the same sprite id, keeps its own row. Reruns change nothing.

CREATE TEMPORARY TABLE `habbo_content_139` LIKE `furniture`;


SELECT n.`item_name`, n.`public_name`, n.`type`, n.`width`, n.`length`, n.`stack_height`, n.`can_stack`, n.`can_sit`, n.`is_walkable`, n.`sprite_id`, n.`allow_recycle`, n.`allow_trade`, n.`allow_marketplace_sell`, n.`allow_gift`, n.`allow_inventory_stack`, n.`interaction_type`, n.`interaction_modes_count`, n.`vending_ids`, n.`height_adjustable`, n.`is_rare`, n.`has_furnidata`, n.`part_colors`, n.`revision`, n.`category`, n.`default_dir`, n.`xdim`, n.`ydim`, n.`name`, n.`description`, n.`ad_url`, n.`excluded_dynamic`, n.`custom_params`, n.`special_type`, n.`can_stand_on`, n.`can_sit_on`, n.`can_lay_on`, n.`can_put_stuff_on`, n.`height`, n.`furni_line`, n.`environment`, n.`rare`, n.`tradeable`, n.`recyclable`
FROM `habbo_content_139` n
WHERE NOT EXISTS (
    SELECT 1 FROM `furniture` f
    WHERE f.`item_name` = n.`item_name` OR f.`furnidata_classname` = n.`item_name`
       OR (f.`type` = n.`type` AND f.`furnidata_sprite_id` = n.`sprite_id`));

DROP TEMPORARY TABLE `habbo_content_139`;
